// GLSL ES 3.0 program tooling — the GL twin of gpu.ts's shaderModule(). GLSL
// compile failures are as silent as WGSL ones (a program just draws nothing),
// so every program in the GL backend compiles through here and logs the info
// log with line context on failure.
//
// CONVENTIONS (shared by every GL twin — keep them or the twins drift):
// - Instance data that WebGPU keeps in a vertex-stage storage buffer becomes an
//   interleaved INSTANCE VBO (`vertexAttribDivisor(loc, 1)`) with the SAME
//   Float32Array packing as the WebGPU batch — layouts are asserted by dist
//   tests, float-for-float.
// - The quad corner (WGSL `vertex_index` bit-twiddling) comes from `gl_VertexID`
//   so no corner VBO is needed; fullscreen passes draw 3 verts the same way.
// - Depth: WGSL writes z01 in [0,1] (bigger engine-z = closer = smaller z01);
//   GL twins emit `gl_Position.z = z01 * 2.0 - 1.0` with LEQUAL — identical
//   ordering semantics.
// - Screen-space uv in fragment shaders follows the WGSL convention (0 = TOP)
//   so ported effect/backdrop code keeps its meaning: derive it as
//   `uv = vec2(gl_FragCoord.x, res.y - gl_FragCoord.y) / res`.
// - Colours are premultiplied OUT of every fragment shader, exactly like the
//   WebGPU pipelines; the canvas is premultiplied-alpha.
//
// Module load is DOM/GL-free; only compileProgram touches the context.

/** Prefix for every shader in the backend (version + float precision). */
export const GLSL_HEADER = '#version 300 es\n';
export const GLSL_FRAG_HEADER = GLSL_HEADER + 'precision highp float;\nprecision highp int;\n';

/**
 * Compile + link a program, logging info logs on failure (with numbered source
 * for shader errors — GLSL error lines are useless without it). Returns null on
 * failure so callers can no-op draw instead of throwing mid-frame.
 */
export function compileProgram(
  gl: WebGL2RenderingContext,
  vsSource: string,
  fsSource: string,
  label: string,
): WebGLProgram | null {
  const compile = (type: number, src: string, kind: string): WebGLShader | null => {
    const sh = gl.createShader(type);
    if (!sh) return null;
    gl.shaderSource(sh, src);
    gl.compileShader(sh);
    if (!gl.getShaderParameter(sh, gl.COMPILE_STATUS) && !gl.isContextLost()) {
      const log = gl.getShaderInfoLog(sh) ?? 'unknown error';
      const numbered = src.split('\n').map((l, i) => `${i + 1}: ${l}`).join('\n');
      console.error(`${label} ${kind} GLSL error:\n${log}\n${numbered}`);
      gl.deleteShader(sh);
      return null;
    }
    return sh;
  };
  const vs = compile(gl.VERTEX_SHADER, vsSource, 'vertex');
  const fs = compile(gl.FRAGMENT_SHADER, fsSource, 'fragment');
  if (!vs || !fs) return null;
  const prog = gl.createProgram();
  if (!prog) return null;
  gl.attachShader(prog, vs);
  gl.attachShader(prog, fs);
  gl.linkProgram(prog);
  gl.deleteShader(vs);
  gl.deleteShader(fs);
  if (!gl.getProgramParameter(prog, gl.LINK_STATUS) && !gl.isContextLost()) {
    console.error(`${label} GLSL link error: ${gl.getProgramInfoLog(prog) ?? 'unknown'}`);
    gl.deleteProgram(prog);
    return null;
  }
  return prog;
}

/**
 * Declare `count` consecutive vec4 instance attributes starting at `firstLoc`,
 * all reading from the currently bound interleaved instance VBO (stride =
 * count*16 bytes). The universal storage-buffer → instanced-attribute mapping.
 */
export function instanceVec4Attribs(
  gl: WebGL2RenderingContext,
  firstLoc: number,
  count: number,
  /**
   * Byte offset of the first instance to read. GL has no `firstInstance` draw
   * parameter, so drawing a SPAN of the buffer means re-pointing the attributes
   * at its start — the same trick the GL UI renderer uses for its runs. 0 (the
   * default) reads from the beginning, which is every single-span caller.
   */
  byteOffset = 0,
): void {
  const stride = count * 16;
  for (let i = 0; i < count; i++) {
    const loc = firstLoc + i;
    gl.enableVertexAttribArray(loc);
    gl.vertexAttribPointer(loc, 4, gl.FLOAT, false, stride, byteOffset + i * 16);
    gl.vertexAttribDivisor(loc, 1);
  }
}

/** Upload an image/canvas source to a straight-alpha RGBA texture (the twin of
 *  atlas.ts textureFromCanvas — same no-premultiply recipe). */
export function textureFromSource(
  gl: WebGL2RenderingContext,
  source: TexImageSource,
  opts: { filter?: 'linear' | 'nearest'; premultiply?: boolean } = {},
): WebGLTexture {
  const tex = gl.createTexture()!;
  gl.bindTexture(gl.TEXTURE_2D, tex);
  gl.pixelStorei(gl.UNPACK_PREMULTIPLY_ALPHA_WEBGL, opts.premultiply ?? false);
  gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, false); // row 0 = image top, matching WebGPU v=0
  gl.pixelStorei(gl.UNPACK_COLORSPACE_CONVERSION_WEBGL, gl.NONE);
  gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, source);
  const f = opts.filter === 'nearest' ? gl.NEAREST : gl.LINEAR;
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, f);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, f);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
  gl.pixelStorei(gl.UNPACK_PREMULTIPLY_ALPHA_WEBGL, false);
  return tex;
}

/** A grow-on-demand instance VBO: upload `count*floatsPer` floats per frame. */
export class InstanceBuffer {
  private vbo: WebGLBuffer | null = null;
  private byteCapacity = 0;

  constructor(private gl: WebGL2RenderingContext) {}

  /** Bind + (re)upload the live prefix of `data`. Returns the bound VBO. */
  upload(data: Float32Array, floatCount: number): WebGLBuffer {
    const gl = this.gl;
    if (!this.vbo) { this.vbo = gl.createBuffer()!; this.byteCapacity = 0; }
    gl.bindBuffer(gl.ARRAY_BUFFER, this.vbo);
    const bytes = data.byteLength;
    if (bytes > this.byteCapacity) {
      gl.bufferData(gl.ARRAY_BUFFER, data.byteLength, gl.DYNAMIC_DRAW);
      this.byteCapacity = bytes;
    }
    gl.bufferSubData(gl.ARRAY_BUFFER, 0, data, 0, floatCount);
    return this.vbo;
  }

  /** Drop the VBO handle (context restore recreates lazily). */
  reset(gl: WebGL2RenderingContext): void {
    this.gl = gl;
    this.vbo = null;
    this.byteCapacity = 0;
  }
}
